    t = 0
    for ch in s:
        if '0' <= ch <= '9':
            t += 1
    return t

def characters(s):
    t = 0
    for ch in s:
        if 'a' <= ch <= 'z' or 'A' <= ch <= 'Z':
            t += 1
    return t
